const vrNeed=L=>Math.round(20*Math.pow(L,1.5));
const vrBase=L=>12+2.4*L;                                    // 同等級的標準攻擊力
const vrHit=(raw,def)=>raw*raw/(raw+Math.max(0,def));          // 防禦公式：永遠打得痛，但不會秒殺
const vrCls=()=>VCLS[vrS().cls||'warrior'];
const vrEqW=()=>{const V=vrS();return V.bag.find(i=>i.id==V.eq.w)||null};
const vrEqA=()=>{const V=vrS();return V.bag.find(i=>i.id==V.eq.a)||null};
const vrAf=k=>[vrEqW(),vrEqA()].reduce((a,i)=>a+((i&&i.af&&i.af[k])||0),0);
const vrReal=(v,b,div)=>Math.min(.3,Math.max(0,(v-b)/div));  // 現實連動最多 +30%
const vrAtk=()=>{const V=vrS(),w=vrEqW();return Math.round(vrBase(V.lv)*vrCls().atk*(1+vrReal(st.pow||30,30,150))*(1+((w&&w.atk)||0)/100+vrAf('atk')/100)*(1+vrTM('atk'))*(1+.01*vrSt('str'))*(1+vrRM('atk')))};
const vrHP=()=>{const V=vrS();return Math.round((100+19*V.lv)*vrCls().hp*(1+vrReal(staMax(),100,300))*(1+vrAf('hp')/100)*(1+vrTM('hp'))*(1+.04*vrSt('vit'))*(1+vrRM('hp')))};
const vrMP=()=>{const V=vrS();return Math.round((50+9*V.lv)*vrCls().mp*(1+vrReal(st.wis||50,50,150))*(1+.03*vrSt('int'))*(1+vrRM('mp'))+vrAf('mp'))};
const vrDef=()=>{const V=vrS(),a=vrEqA();return Math.round(((2+1.5*V.lv)*vrCls().def+((a&&a.def)||0))*(1+vrTM('def'))*(1+.02*vrSt('vit'))*(1+vrRM('def')))};
const vrCrit=()=>Math.min(.6,.05+Math.min(.1,((st.gym&&st.gym.streak)||0)*.02)+vrCls().crit+vrAf('crit')/100+vrTM('crit')+.005*vrSt('luk')+.0025*vrSt('agi')+vrRM('crit'));
