function vrMkItem(t,r,lv,b){const it={id:++VRID,t,r,lv,af:{}};if(t=='w'){it.b=b||Object.keys(VWP)[Math.floor(Math.random()*Object.keys(VWP).length)];it.atk=[0,8,16,26,40][r]+Math.floor(lv/2)}else{it.def=Math.round((2+lv*.8)*(1+r*.3));it.n=['皮甲','鎖子甲','騎士鎧','法袍','遊俠斗篷'][Math.floor(Math.random()*5)]}
 const ks=Object.keys(AFX).sort(()=>Math.random()-.5).slice(0,r);ks.forEach(k=>{const A=AFX[k];it.af[k]=Math.round(A[1]+Math.random()*(A[2]-A[1]))});if(r==4)it.leg=1;return it}
function vrRollRar(boss){const w=boss=='elite'?[15,45,28,10,2]:boss?[0,40,40,16,4]:[60,28,9,2.6,.4];let x=Math.random()*w.reduce((a,b)=>a+b,0);for(let i=0;i<5;i++){x-=w[i];if(x<=0)return i}return 0}
