const vrItDesc=it=>(it.t=='w'?`攻擊 +${it.atk}%`:`防禦 +${it.def}`)+Object.entries(it.af).map(([k,v])=>`・${AFX[k][0]} ${k=='cdr'?'-':'+'}${v}${AFX[k][3]}`).join('')+(it.leg?'・🔥 攻擊附帶燃燒':'')+`（Lv.${it.lv}）`;
const vrItHTML=it=>`<span style="color:${VRAR[it.r][1]};font-weight:bold;text-shadow:0 1px 0 #000">[${VRAR[it.r][0]}] ${vrItName(it)}</span>`;
