// ───────── 每日任務 ─────────
function vrDaily(){const V=vrS(),dk=T.year*400+T.day;if(V.daily&&V.daily.d==dk)return V.daily;
 const pool=[{t:'打倒 15 隻史萊姆',k:'kill',m:'slime',g:15},{t:'打倒 6 隻野狼',k:'kill',m:'wolf',g:6},{t:'打倒 5 隻毒蘑菇',k:'kill',m:'shroom',g:5},{t:'抵達第 3 層',k:'floor',g:3},{t:'打倒史萊姆國王',k:'kill',m:'boss',g:1},{t:'撿到 1 件精良以上的裝備',k:'loot',g:1},{t:'使用 10 次技能',k:'skill',g:10}];
 const q=pool.sort(()=>Math.random()-.5).slice(0,3).map(x=>({...x,n:0,done:0}));V.daily={d:dk,q};return V.daily}
function vrQuest(k,m,n){const D=vrDaily();D.q.forEach(q=>{if(q.done||q.k!=k||(q.m&&q.m!=m))return;q.n=k=='floor'?Math.max(q.n,n):q.n+(n||1);if(q.n>=q.g){q.done=1;const V=vrS();V.gold+=150;V.mat.bone=(V.mat.bone||0)+2;toast('📜 每日任務完成：'+q.t+'（💠+150・獸骨×2）')}})}
