function vrLobby(){const V=vrS();if(!V.cls)return vrClassPick(true);const C=vrCls(),w=vrEqW(),a=vrEqA(),D=vrDaily();
 openDlg('🥽 幻境 Online・大廳',`${C.ic} <b>${C.n}</b>　Lv.<b>${V.lv}</b>${V.lv>=V.cap?'（已達上限 '+V.cap+'）':''}　經驗 ${V.exp}/${vrNeed(V.lv)}　💠 <b>${V.gold}</b><br>
  武器：${w?vrItHTML(w):'—'}　防具：${a?vrItHTML(a):'（無）'}<br>
  <span style="font-size:12px;opacity:.85">攻擊 ${vrAtk()}・血量 ${vrHP()}・魔力 ${vrMP()}・防禦 ${vrDef()}・爆擊 ${Math.round(vrCrit()*100)}%</span><br>
  <span style="font-size:12px">👥 隊友：${V.party.map(id=>VPAL[id].n).join('、')||'（單人）'}　📜 每日任務 ${D.q.filter(q=>q.done).length}/3</span>`,
 [['⚔️ 出發！',`綠綠草原（建議 Lv.2～10）・從第 ${V.ckpt} 層開始`,()=>{closeDlg();vrGame(V.ckpt)}],
  ['🎒 裝備與背包',`${V.bag.length}/30 件・換裝、賣掉不要的`,vrBag],['👥 組隊','找朋友一起打（最多 2 人）',vrParty],['📜 每日任務',D.q.map(q=>(q.done?'✅':'⬜')+q.t).join('　'),vrDailyView],
  ['📖 怪物圖鑑','打倒 10 隻、50 隻有獎勵',vrDex],['🗡️ 武器店','買普通品質的武器',vrWeapons],['🧪 道具店','藥水、烤肉、麵包',vrShop],
  ['💎 賣素材',Object.entries(V.mat).filter(q=>q[1]).map(([k,n])=>VMAT[k][0]+'×'+n).join('、')||'沒有素材',()=>{let g=0;for(const k in V.mat){g+=V.mat[k]*6;V.mat[k]=0}V.gold+=g;SVDIRTY=1;toast('💠 賣掉素材，獲得幻境幣 '+g);vrLobby()},!Object.values(V.mat).some(n=>n)],
  ['🔄 轉職',`目前：${C.n}・換職業不會掉等級`,()=>vrClassPick(false)],['📖 操作說明','',vrHelp],['🚪 摘下頭盔','回到現實',closeDlg]])}
function vrHelp(){openDlg('📖 幻境 Online 操作',`<b>移動</b>：←→／AD（橫向平台，像楓之谷）　<b>跳</b>：空白鍵／K（按住↓再跳可以跳下平台）　<b>繩子</b>：站在繩子旁按 ↑↓ 爬<br><b>普攻</b>：J／Z（按住連打）・會自動瞄準前方最近的怪（斜上斜下也打得到）・按住 ↑／↓ 強制往上、往下打　<b>衝刺</b>：Shift／L（無敵）　<b>技能</b>：Q・E（武器技）・R（職業大招）<br><b>道具</b>：1～4　<b>換武器</b>：Tab（背包裡、職業能用的武器輪流換）　<b>離開</b>：Esc<br><br>
 <b>傷害公式</b>：攻擊 × 攻擊 ÷（攻擊＋防禦）——防禦再高也會痛一點、攻擊再高也不會秒殺。<br><b>等級</b>：綠綠草原上限 Lv.10。打比你低 5 級以上的怪，經驗只剩 10%。<br><b>現實連動</b>：力量、體力上限、智慧、連續健身，最多讓你強 30%，認真健身有感，但還是要靠技術。`,[['返回','',vrLobby]])}
function vrClassPick(first){openDlg(first?'🥽 選擇你的職業':'🔄 轉職',(first?'「冒險者，請選擇你在幻境世界的職業。」<br>':'')+'之後可以在大廳免費轉職，等級和裝備都會保留（但只能用該職業的武器）。',Object.entries(VCLS).map(([k,C])=>[`${C.ic} ${C.n}`,C.d+'<br>被動：'+C.pas+'・大招：'+VSK[C.R].n+'・武器：'+C.wp.map(b=>VWP[b].n).join('、'),()=>{const V=vrS();V.cls=k;
  if(!C.wp.includes((vrEqW()||{}).b)){let it=V.bag.find(i=>i.t=='w'&&C.wp.includes(i.b));if(!it){it=vrMkItem('w',0,1,C.wp[0]);V.bag.push(it)}V.eq.w=it.id;V.cur=it.b}SVDIRTY=1;toast(C.ic+' 成為'+C.n+'！');vrLobby()}]).concat(first?[]:[['返回','',vrLobby]]))}
function vrBag(sel){const V=vrS(),C=vrCls();const o=V.bag.slice().sort((a,b)=>b.r-a.r||b.lv-a.lv).map(it=>{const on=V.eq.w==it.id||V.eq.a==it.id,ok=it.t=='a'||C.wp.includes(it.b);
  return[(on?'✅ ':'')+vrItHTML(it),vrItDesc(it)+(ok?'':'・⚠️ '+C.n+'不能用'),()=>vrItem(it.id)]});
 openDlg('🎒 裝備與背包',`${V.bag.length}/30 件・點裝備可以穿上或賣掉`,o.concat([['💰 賣掉全部「普通」（沒穿的）','',()=>{const s=V.bag.filter(i=>i.r==0&&i.id!=V.eq.w&&i.id!=V.eq.a);V.gold+=s.length*8;V.bag=V.bag.filter(i=>!s.includes(i));SVDIRTY=1;toast('💠 +'+s.length*8);vrBag()}],['返回','',vrLobby]]))}
function vrItem(id){const V=vrS(),it=V.bag.find(i=>i.id==id),C=vrCls(),on=V.eq.w==id||V.eq.a==id,ok=it.t=='a'||C.wp.includes(it.b),price=[8,25,60,150,400][it.r]+it.lv*2;
 openDlg(vrItName(it),vrItHTML(it)+'<br>'+vrItDesc(it),[[on?'（穿著中）':'👕 穿上',ok?'':C.n+'不能用這種武器',()=>{if(it.t=='w'){V.eq.w=id;V.cur=it.b}else V.eq.a=id;SVDIRTY=1;vrBag()},on||!ok],['💰 賣掉（💠'+price+'）','',()=>{V.bag=V.bag.filter(i=>i!==it);V.gold+=price;SVDIRTY=1;vrBag()},on],['返回','',()=>vrBag()]])}
function vrWeapons(){const V=vrS(),C=vrCls();openDlg('🗡️ 幻境武器店',`💠 ${V.gold}・這裡只賣「普通」品質，好裝備要靠打怪掉`,Object.entries(VWP).map(([k,w])=>[`${w.ic} ${w.n}　💠${w.price}`,w.d+'・技能：'+w.sk.map(s=>VSK[s].n).join('／')+(C.wp.includes(k)?'':'・⚠️ '+C.n+'不能用'),()=>{if(V.bag.length>=30)return toast('背包滿了');V.gold-=w.price;V.bag.push(vrMkItem('w',0,V.lv,k));SVDIRTY=1;toast('🗡️ 買了'+w.n);vrWeapons()},V.gold<w.price]).concat([['返回','',vrLobby]]))}
